package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.time.LocalDate;
import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String bookId = registerBook();
        String loanRequest = loanRequest(bookId, registerMember());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bookId").value(bookId));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest))
                .andExpect(status().isConflict());
    }

    @Test
    void sixth_loan_for_same_member_returns_409_with_loan_limit_exceeded() throws Exception {
        String memberId = registerMember();
        for (int i = 0; i < 5; i++) {
            mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(registerBook(), memberId)))
                    .andExpect(status().isCreated());
        }

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void loaning_with_unregistered_member_returns_404() throws Exception {
        String bookId = registerBook();

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, UUID.randomUUID().toString())))
                .andExpect(status().isNotFound());
    }

    @Test
    void returning_a_loan_returns_200_and_makes_the_book_available_again() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember());

        mockMvc.perform(post("/loans/" + loanId + "/return"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value(LocalDate.now().toString()));

        mockMvc.perform(get("/books/" + bookId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("AVAILABLE"));

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, registerMember())))
                .andExpect(status().isCreated());
    }

    @Test
    void returning_an_already_returned_loan_returns_409_with_already_returned() throws Exception {
        String loanId = loanBook(registerBook(), registerMember());
        mockMvc.perform(post("/loans/" + loanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(post("/loans/" + loanId + "/return"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RETURNED"));
    }

    @Test
    void returning_an_unknown_loan_returns_404() throws Exception {
        mockMvc.perform(post("/loans/" + UUID.randomUUID() + "/return"))
                .andExpect(status().isNotFound());
    }

    @Test
    void returned_loans_do_not_count_toward_the_member_loan_limit() throws Exception {
        String memberId = registerMember();
        String firstLoanId = null;
        for (int i = 0; i < 5; i++) {
            String loanId = loanBook(registerBook(), memberId);
            if (firstLoanId == null) {
                firstLoanId = loanId;
            }
        }
        mockMvc.perform(post("/loans/" + firstLoanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(registerBook(), memberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("LOAN_LIMIT_EXCEEDED"));
    }

    @Test
    void returning_on_the_due_date_has_no_overdue_days_and_no_late_fee() throws Exception {
        String loanId = loanBookOn(registerBook(), registerMember(), "2026-01-01");

        mockMvc.perform(returnOn(loanId, "2026-01-15"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanId").value(loanId))
                .andExpect(jsonPath("$.returnedAt").value("2026-01-15"))
                .andExpect(jsonPath("$.overdueDays").value(0))
                .andExpect(jsonPath("$.lateFee").value(0));
    }

    @Test
    void returning_one_day_late_charges_100_won() throws Exception {
        String loanId = loanBookOn(registerBook(), registerMember(), "2026-01-01");

        mockMvc.perform(returnOn(loanId, "2026-01-16"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(1))
                .andExpect(jsonPath("$.lateFee").value(100));
    }

    @Test
    void returning_five_days_late_charges_500_won() throws Exception {
        String loanId = loanBookOn(registerBook(), registerMember(), "2026-01-01");

        mockMvc.perform(returnOn(loanId, "2026-01-20"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.overdueDays").value(5))
                .andExpect(jsonPath("$.lateFee").value(500));
    }

    @Test
    void returning_before_the_loan_date_returns_400() throws Exception {
        String loanId = loanBookOn(registerBook(), registerMember(), "2026-01-10");

        mockMvc.perform(returnOn(loanId, "2026-01-09"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void loan_with_loaned_at_sets_due_date_fourteen_days_later() throws Exception {
        String bookId = registerBook();
        String memberId = registerMember();

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId, "loanedAt", "2026-01-01"))))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.loanedAt").value("2026-01-01"))
                .andExpect(jsonPath("$.dueAt").value("2026-01-15"));
    }

    @Test
    void member_loans_lists_active_loans_with_title_and_dates() throws Exception {
        String memberId = registerMember();
        String bookId = registerBookTitled("Clean Code");
        String loanId = loanBookOn(bookId, memberId, "2026-02-02");

        mockMvc.perform(get("/members/" + memberId + "/loans"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items[0].loanId").value(loanId))
                .andExpect(jsonPath("$.items[0].bookId").value(bookId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void member_loans_excludes_returned_loans_and_counts_only_active_ones() throws Exception {
        String memberId = registerMember();
        String returnedLoanId = loanBookOn(registerBook(), memberId, "2026-01-01");
        loanBookOn(registerBook(), memberId, "2026-01-05");
        mockMvc.perform(returnOn(returnedLoanId, "2026-01-03")).andExpect(status().isOk());

        mockMvc.perform(get("/members/" + memberId + "/loans"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void member_loans_pages_results_and_total_count_ignores_page() throws Exception {
        String memberId = registerMember();
        loanBookOn(registerBook(), memberId, "2026-01-01");
        loanBookOn(registerBook(), memberId, "2026-01-02");
        loanBookOn(registerBook(), memberId, "2026-01-03");

        mockMvc.perform(get("/members/" + memberId + "/loans").param("page", "0").param("size", "2"))
