package com.example.lending.domain;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;

/**
 * 한 도서의 예약 줄. 목록의 앞쪽일수록 먼저 빌릴 차례다.
 */
public class ReservationQueue {

    private final UUID bookId;
    private final List<Reservation> reservations;

    public ReservationQueue(UUID bookId, List<Reservation> reservations) {
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.reservations = new ArrayList<>(reservations);
    }

    public Reservation enqueue(UUID memberId) {
        boolean alreadyReserved = reservations.stream()
                .anyMatch(reservation -> reservation.getMemberId().equals(memberId));
        if (alreadyReserved) {
            throw new AlreadyReservedException(bookId, memberId);
        }
        Reservation reservation = Reservation.place(bookId, memberId);
        reservations.add(reservation);
        return reservation;
    }

    public int positionOf(UUID reservationId) {
        for (int i = 0; i < reservations.size(); i++) {
            if (reservations.get(i).getId().equals(reservationId)) {
                return i + 1;
            }
        }
        throw new IllegalArgumentException("reservation is not in the queue: " + reservationId);
    }

    /**
     * 이 회원이 빌릴 수 있는지 확인하고, 빌리면 소진될 예약을 돌려준다.
     * 예약이 없으면 빈 Optional 을 돌려주고, 맨 앞 예약자가 아니면 예외를 던진다.
     */
    public Optional<Reservation> claimFor(UUID memberId) {
        if (reservations.isEmpty()) {
            return Optional.empty();
        }
        Reservation front = reservations.get(0);
        if (!front.getMemberId().equals(memberId)) {
            throw new ReservedForOtherException(bookId);
        }
        return Optional.of(front);
    }

    public List<Reservation> getReservations() {
        return List.copyOf(reservations);
    }
}
