package com.example.lending.adapter.in.web;

import com.example.lending.application.port.in.GetReservationQueueUseCase;
import com.example.lending.application.port.in.QueuedReservation;
import com.example.lending.application.port.in.ReserveBookUseCase;
import com.example.lending.application.port.in.ReserveBookUseCase.ReserveBookCommand;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.UUID;

@RestController
@RequestMapping("/books/{bookId}/reservations")
public class ReservationController {

    private final ReserveBookUseCase reserveBookUseCase;
    private final GetReservationQueueUseCase getReservationQueueUseCase;

    public ReservationController(ReserveBookUseCase reserveBookUseCase,
                                 GetReservationQueueUseCase getReservationQueueUseCase) {
        this.reserveBookUseCase = reserveBookUseCase;
        this.getReservationQueueUseCase = getReservationQueueUseCase;
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ReserveBookResponse reserveBook(@PathVariable UUID bookId, @RequestBody ReserveBookRequest request) {
        QueuedReservation queued = reserveBookUseCase.reserveBook(new ReserveBookCommand(bookId, request.memberId()));
        return ReserveBookResponse.from(queued);
    }

    @GetMapping
    public List<ReservationQueueItemResponse> getReservationQueue(@PathVariable UUID bookId) {
        return getReservationQueueUseCase.getReservationQueue(bookId).stream()
                .map(ReservationQueueItemResponse::from)
                .toList();
    }
}
