package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class ReservationIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void reserving_a_book_on_loan_returns_201_and_queue_positions_follow_arrival_order() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());

        reserve(bookId, registerMember())
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.reservationId").isNotEmpty())
                .andExpect(jsonPath("$.position").value(1));
        reserve(bookId, registerMember())
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(2));

        mockMvc.perform(get("/books/" + bookId + "/reservations"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(2))
                .andExpect(jsonPath("$[0].position").value(1))
                .andExpect(jsonPath("$[0].memberId").isNotEmpty())
                .andExpect(jsonPath("$[1].position").value(2));
    }

    @Test
    void reserving_an_available_book_returns_409_with_book_available() throws Exception {
        reserve(registerBook(), registerMember())
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_AVAILABLE"));
    }

    @Test
    void reserving_a_discarded_book_returns_409_with_book_discarded() throws Exception {
        String bookId = registerBook();
        mockMvc.perform(post("/books/" + bookId + "/discard")).andExpect(status().isOk());

        reserve(bookId, registerMember())
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("BOOK_DISCARDED"));
    }

    @Test
    void reserving_the_same_book_twice_returns_409_with_already_reserved() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());
        String memberId = registerMember();
        reserve(bookId, memberId).andExpect(status().isCreated());

        reserve(bookId, memberId)
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ALREADY_RESERVED"));
    }

    @Test
    void reserving_with_unregistered_member_returns_404() throws Exception {
        String bookId = registerBook();
        loanBook(bookId, registerMember());

        reserve(bookId, UUID.randomUUID().toString()).andExpect(status().isNotFound());
    }

    @Test
    void reserving_an_unknown_book_returns_404() throws Exception {
        reserve(UUID.randomUUID().toString(), registerMember()).andExpect(status().isNotFound());
    }

    @Test
    void after_return_only_the_front_reserver_can_borrow() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember());
        String frontMemberId = registerMember();
        String secondMemberId = registerMember();
        reserve(bookId, frontMemberId).andExpect(status().isCreated());
        reserve(bookId, secondMemberId).andExpect(status().isCreated());
        mockMvc.perform(post("/loans/" + loanId + "/return")).andExpect(status().isOk());

        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, secondMemberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, frontMemberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void front_reserver_borrowing_consumes_the_reservation_and_next_reserver_becomes_front() throws Exception {
        String bookId = registerBook();
        String firstLoanId = loanBook(bookId, registerMember());
        String frontMemberId = registerMember();
        String secondMemberId = registerMember();
        reserve(bookId, frontMemberId).andExpect(status().isCreated());
        reserve(bookId, secondMemberId).andExpect(status().isCreated());
        mockMvc.perform(post("/loans/" + firstLoanId + "/return")).andExpect(status().isOk());
        loanBook(bookId, frontMemberId);

        mockMvc.perform(get("/books/" + bookId + "/reservations"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].memberId").value(secondMemberId))
                .andExpect(jsonPath("$[0].position").value(1));

        String secondLoanId = loanBook(bookId, frontMemberId, false);
        mockMvc.perform(post("/loans/" + secondLoanId + "/return")).andExpect(status().isOk());
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, frontMemberId)))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("RESERVED_FOR_OTHER"));
        mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(loanRequest(bookId, secondMemberId)))
                .andExpect(status().isCreated());
    }

    @Test
    void book_without_reservations_can_be_borrowed_by_anyone_after_return() throws Exception {
        String bookId = registerBook();
        String loanId = loanBook(bookId, registerMember());
        mockMvc.perform(post("/loans/" + loanId + "/return")).andExpect(status().isOk());

        loanBook(bookId, registerMember());
    }

    @Test
    void reservation_queue_for_unknown_book_returns_404() throws Exception {
        mockMvc.perform(get("/books/" + UUID.randomUUID() + "/reservations"))
                .andExpect(status().isNotFound());
    }

    private org.springframework.test.web.servlet.ResultActions reserve(String bookId, String memberId) throws Exception {
        return mockMvc.perform(post("/books/" + bookId + "/reservations").contentType(MediaType.APPLICATION_JSON)
                .content(objectMapper.writeValueAsString(Map.of("memberId", memberId))));
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        return loanBook(bookId, memberId, true);
    }

    private String loanBook(String bookId, String memberId, boolean expectCreated) throws Exception {
        var action = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                .content(loanRequest(bookId, memberId)));
        if (expectCreated) {
            action.andExpect(status().isCreated());
        }
        String loaned = action.andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }

    private String loanRequest(String bookId, String memberId) throws Exception {
        return objectMapper.writeValueAsString(Map.of("bookId", bookId, "memberId", memberId));
    }
}
